// Ported from directus/app/src/lang/index.ts
// Backoffice: messages are the JSON generated by scripts/sync-translations.mjs (rebranded, FR-062) with the
// Backoffice-only overlay merged on top; a missing key logs one recognizable warning (E2E fails on it).
import { createI18n, type I18nOptions } from 'vue-i18n';
import availableLanguages from './available-languages.json';
import datetimeFormats from './date-formats.json';
import numberFormats from './number-formats.json';
import enUSOverlay from './overlay/en-US.ts';
import enUSBase from './translations/en-US.json';

export const FALLBACK_LANGUAGE = 'en-US';
export const MISSING_KEY_WARNING = '[i18n] missing key:';

const warnedKeys = new Set<string>();

export const i18n = createI18n({
	legacy: false,
	locale: FALLBACK_LANGUAGE,
	fallbackLocale: FALLBACK_LANGUAGE,
	messages: {
		[FALLBACK_LANGUAGE]: { ...enUSBase, ...enUSOverlay },
	} as NonNullable<I18nOptions['messages']>,
	// Backoffice: Directus sets silentTranslationWarn (legacy mode only); falling back to en-US stays silent, a key
	// missing from en-US as well warns once. vue-i18n calls `missing` for several locales of the chain per lookup.
	missingWarn: false,
	fallbackWarn: false,
	missing: (_locale, key, _instance, type) => {
		if (type !== 'translate' || warnedKeys.has(key) || i18n.global.te(key, FALLBACK_LANGUAGE)) return;
		warnedKeys.add(key);
		// eslint-disable-next-line no-console
		console.warn(MISSING_KEY_WARNING, key);
	},
	datetimeFormats: datetimeFormats as NonNullable<I18nOptions['datetimeFormats']>,
	numberFormats: numberFormats as NonNullable<I18nOptions['numberFormats']>,
});

export type Language = keyof typeof availableLanguages;

export const loadedLanguages: Language[] = [FALLBACK_LANGUAGE];

type ErrorList = { extensions?: { code?: unknown } }[];

/**
 * An error code, an error rejected by the SDK ({ errors: [{ message, extensions: { code } }] }) or an axios-like
 * error ({ response: { data: { errors } } }).
 */
export type APIError = string | { errors?: ErrorList | unknown; response?: { data?: { errors?: ErrorList } } };

export function translateAPIError(error: APIError | null | undefined): string {
	const defaultMsg = i18n.global.t('unexpected_error');

	let code: unknown = error;

	if (typeof error === 'object' && error !== null) {
		const errors = Array.isArray(error.errors) ? (error.errors as ErrorList) : error.response?.data?.errors;
		code = errors?.[0]?.extensions?.code;
	}

	if (!error || !code || typeof code !== 'string') return defaultMsg;

	const key = `errors.${code}`;
	const exists = i18n.global.te(key);

	if (exists === false) return defaultMsg;

	return i18n.global.t(key);
}
